// 将ip 转换为long
long parseIP(string &ip) {
    vector<string> ipBlock = split(ip, ".");
    long res  = 0;
    for (int i = 0; i < 4; i++) {
        res = (res << 8) | stol(ipBlock[i]);
    }
    return res;
}
​
// 自定义排序
bool cmp(IPRange i1, IPRange i2) {
    return i1.start < i2.start;
}
