import java.util.*;
​
public class Main {
    // IP 段结构体
    static class IPRange {
        long start;
        long end;
        String city;
​
        IPRange(long start, long end, String city) {
            this.start = start;
            this.end = end;
            this.city = city;
        }
    }
​
    // 将 IP 字符串转为 long 类型
    static long parseIP(String ip) {
        String[] parts = ip.split("\\.");
        long res = 0;
        for (int i = 0; i < 4; i++) {
            res = (res << 8) | Integer.parseInt(parts[i]);
        }
        return res;
    }
​
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
​
        // 读取城市IP段信息
        String cityIPLine = sc.nextLine();
        // 读取查询IP列表
        String searchIPLine = sc.nextLine();
​
        String[] cityList = cityIPLine.split(";");
        List<IPRange> ipRanges = new ArrayList<>();
​
        // 解析城市IP段列表
        for (String entry : cityList) {
            String[] parts = entry.split("=");
            String cityName = parts[0];
            String[] ips = parts[1].split(",");
            long start = parseIP(ips[0]);
            long end = parseIP(ips[1]);
            ipRanges.add(new IPRange(start, end, cityName));
        }
​
        // 按 start 升序排序
        ipRanges.sort(Comparator.comparingLong(a -> a.start));
​
        // 解析查询IP
        String[] searchIPs = searchIPLine.split(",");
        int m = searchIPs.length;
        long[] searchLongs = new long[m];
        for (int i = 0; i < m; i++) {
            searchLongs[i] = parseIP(searchIPs[i]);
        }
​
        // 对查询IP按值排序，记录原始索引
        Integer[] qIndex = new Integer[m];
        for (int i = 0; i < m; i++) qIndex[i] = i;
        Arrays.sort(qIndex, Comparator.comparingLong(i -> searchLongs[i]));
​
        // 最小堆：按区间长度升序（length, end, index）
        PriorityQueue<long[]> heap = new PriorityQueue<>(Comparator
            .comparingLong((long[] a) -> a[0])       // 先按区间长度升序
            .thenComparingLong(a -> a[1])            // 然后按 end 升序
        );
​
​
        // 存储最终结果
        String[] res = new String[m];
        int j = 0;
​
        for (int qi : qIndex) {
            long ipVal = searchLongs[qi];
​
            // 将起点 <= 查询IP 的所有段入堆
            while (j < ipRanges.size() && ipRanges.get(j).start <= ipVal) {
                IPRange range = ipRanges.get(j);
                long len = range.end - range.start + 1;
                heap.offer(new long[]{len, range.end, j});
                j++;
            }
​
            // 移除所有 end < 查询IP 的无效段
            while (!heap.isEmpty() && heap.peek()[1] < ipVal) {
                heap.poll();
            }
​
            // 堆顶即为最佳匹配段
            if (!heap.isEmpty()) {
                res[qi] = ipRanges.get((int) heap.peek()[2]).city;
            } else {
                res[qi] = ""; // 没有匹配城市
            }
        }
​
        // 输出查询结果，用逗号连接
        for (int i = 0; i < m; i++) {
            System.out.print(res[i]);
            if (i != m - 1) System.out.print(",");
        }
    }
}
