// IP 字符串转整数
function parseIP(ip) {
    return ip.split(".").reduce((acc, part) => (acc << 8) | Number(part), 0);
}
​
// 自定义最小堆（按 length 升序，length 相同按 end 升序）
class MinHeap {
    constructor() {
        this.data = [];
    }
​
    // 上浮
    _siftUp(idx) {
        while (idx > 0) {
            const parent = (idx - 1) >> 1;
            if (this._compare(idx, parent) < 0) {
                [this.data[idx], this.data[parent]] = [this.data[parent], this.data[idx]];
                idx = parent;
            } else {
                break;
            }
        }
    }
​
    // 下沉
    _siftDown(idx) {
        const n = this.data.length;
        while (true) {
            let smallest = idx;
            const left = idx * 2 + 1;
            const right = idx * 2 + 2;
​
            if (left < n && this._compare(left, smallest) < 0) smallest = left;
            if (right < n && this._compare(right, smallest) < 0) smallest = right;
​
            if (smallest !== idx) {
                [this.data[idx], this.data[smallest]] = [this.data[smallest], this.data[idx]];
                idx = smallest;
            } else break;
        }
    }
​
    // 比较函数：按长度升序，长度相同按 end 升序
    _compare(i, j) {
        const a = this.data[i], b = this.data[j];
        if (a[0] !== b[0]) return a[0] - b[0];
        return a[1] - b[1];
    }
​
    push(val) {
        this.data.push(val);
        this._siftUp(this.data.length - 1);
    }
​
    pop() {
        const top = this.data[0];
        const last = this.data.pop();
        if (this.data.length > 0) {
            this.data[0] = last;
            this._siftDown(0);
        }
        return top;
    }
​
    peek() {
        return this.data[0];
    }
​
    size() {
        return this.data.length;
    }
}
