    const cityLine = lines[0];
    const searchLine = lines[1];
​
    let ipRanges = [];
​
    // 解析城市 IP 段
    cityLine.split(";").forEach(entry => {
        const [city, ipPair] = entry.split("=");
        const [startStr, endStr] = ipPair.split(",");
        ipRanges.push({
            start: parseIP(startStr),
            end: parseIP(endStr),
            city: city
        });
    });
​
    // 按起点升序排序
    ipRanges.sort((a, b) => a.start - b.start);
​
    const searchIPs = searchLine.split(",");
    const m = searchIPs.length;
    const searchVals = searchIPs.map(parseIP);
    const qIndex = Array.from({ length: m }, (_, i) => i).sort((i, j) => searchVals[i] - searchVals[j]);
​
    let res = Array(m).fill("");
    let heap = new MinHeap();
​
    let j = 0;
    for (let qi of qIndex) {
        const ipVal = searchVals[qi];
​
        // 将所有起点 <= ipVal 的段入堆
        while (j < ipRanges.length && ipRanges[j].start <= ipVal) {
            const r = ipRanges[j];
            const length = r.end - r.start + 1;
            heap.push([length, r.end, j]); // (length, end, index)
            j++;
        }
​
        // 移除 end < ipVal 的无效段
        while (heap.size() > 0 && heap.peek()[1] < ipVal) {
            heap.pop();
        }
​
        if (heap.size() > 0) {
            res[qi] = ipRanges[heap.peek()[2]].city;
        }
    }
