package main
​
import (
    "bufio"
    "container/heap"
    "fmt"
    "os"
    "sort"
    "strconv"
    "strings"
)
​
// IPRange 结构体，表示一个城市对应的 IP 区间
type IPRange struct {
    start int64
    end   int64
    city  string
}
​
// Item 是堆中元素，保存的是 (区间长度, 结束位置, 原始下标)
type Item struct {
    length int64
    end    int64
    index  int
}
​
// MinHeap 是一个最小堆，优先按 length，再按 end 排序
type MinHeap []Item
​
func (h MinHeap) Len() int { return len(h) }
func (h MinHeap) Less(i, j int) bool {
    if h[i].length == h[j].length {
        return h[i].end < h[j].end
    }
    return h[i].length < h[j].length
}
func (h MinHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *MinHeap) Push(x interface{}) { *h = append(*h, x.(Item)) }
func (h *MinHeap) Pop() interface{} {
    old := *h
    x := old[len(old)-1]
    *h = old[:len(old)-1]
    return x
}
​
// parseIP 将 IPv4 字符串解析为 int64 表示
func parseIP(ip string) int64 {
    parts := strings.Split(ip, ".")
    var res int64
    for _, p := range parts {
        v, _ := strconv.ParseInt(p, 10, 64)
        res = (res << 8) | v
    }
    return res
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
​
    // 读取两行输入
    cityLine, _ := reader.ReadString('\n')
    searchLine, _ := reader.ReadString('\n')
    cityLine = strings.TrimSpace(cityLine)
    searchLine = strings.TrimSpace(searchLine)
​
    var ipRanges []IPRange
​
    // 解析城市=起始IP,结束IP 格式
    for _, entry := range strings.Split(cityLine, ";") {
        parts := strings.Split(entry, "=")
        city := parts[0]
        ips := strings.Split(parts[1], ",")
        start := parseIP(ips[0])
        end := parseIP(ips[1])
        ipRanges = append(ipRanges, IPRange{start, end, city})
    }
​
    // 按 IP 起点升序排列
    sort.Slice(ipRanges, func(i, j int) bool {
        return ipRanges[i].start < ipRanges[j].start
    })
​
    // 查询 IP 列表
    searchIPs := strings.Split(searchLine, ",")
    m := len(searchIPs)
    searchVals := make([]int64, m)
    for i := 0; i < m; i++ {
        searchVals[i] = parseIP(searchIPs[i])
    }
​
    // qIndex 用于排序后的查询 IP 索引（记录原始位置）
    qIndex := make([]int, m)
    for i := 0; i < m; i++ {
        qIndex[i] = i
    }
​
    sort.Slice(qIndex, func(i, j int) bool {
        return searchVals[qIndex[i]] < searchVals[qIndex[j]]
    })
​
    // 最小堆，保存候选区间
    h := &MinHeap{}
    heap.Init(h)
​
    res := make([]string, m)
    j := 0
​
    for _, qi := range qIndex {
        ipVal := searchVals[qi]
​
        // 将所有起点 <= 查询 IP 的区间加入堆
        for j < len(ipRanges) && ipRanges[j].start <= ipVal {
            r := ipRanges[j]
            length := r.end - r.start + 1
            heap.Push(h, Item{length, r.end, j})
            j++
        }
​
        // 移除无效的区间（end < ipVal）
        for h.Len() > 0 && (*h)[0].end < ipVal {
            heap.Pop(h)
        }
​
        // 如果堆非空，堆顶就是最优匹配区间
        if h.Len() > 0 {
            res[qi] = ipRanges[(*h)[0].index].city
        } else {
            res[qi] = ""
        }
    }
​
    // 输出结果，逗号分隔
    fmt.Print(strings.Join(res, ","))
}
